function minimumRemoval(beans) {
  const sorted = [...beans].sort((a, b) => a - b);
  const n = sorted.length;
  let total = 0;
  for (const count of sorted) {
    total += count;
  }

  let bestKept = 0;
  for (let i = 0; i < n; i++) {
    const kept = sorted[i] * (n - i);
    if (kept > bestKept) {
      bestKept = kept;
    }
  }
  return total - bestKept;
}

