function minimumRemoval(beans) {
  let max = 0;
  for (const b of beans) max = Math.max(max, b);
  let best = Infinity;
  for (let level = 0; level <= max; level++) {
    let removed = 0;
    for (const b of beans) removed += b < level ? b : b - level;
    best = Math.min(best, removed);
  }
  return best;
}

